const tags = Array.isArray(msg.payload) ? msg.payload : [];
if (!tags.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no tags' });
    return null;
}

const pmsBase = flow.get('pmsBase') || 'http://192.168.1.113:8010';
const machineId = flow.get('machineId') || 1;
const deviceId = flow.get('deviceId') || 10;
const deviceName = flow.get('deviceName') || 'CN01';

msg.method = 'POST';
msg.url = pmsBase + '/api/machines/cnc-live';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    machine_id: machineId,
    tags: tags,
    device_id: deviceId,
    device_name: deviceName,
    source: 'nodered'
};

const blank = tags.filter(t => t && (t.value === '' || t.value == null)).length;
node.status({
    fill: blank === tags.length ? 'red' : 'green',
    shape: 'dot',
    text: tags.length + ' tags → CN' + (machineId === 1 ? '01' : machineId) +
        (blank === tags.length ? ' (all blank/offline)' : '')
});
return msg;

const tags = Array.isArray(msg.payload) ? msg.payload : [];

let statusObj = tags.find(item => {
    let n = item.name || item.displayName?.text || item.displayName || '';
    return typeof n === 'string' && n.toLowerCase() === 'statuscode';
});
let cncStatusObj = tags.find(item => {
    let n = item.name || '';
    return typeof n === 'string' && n.toLowerCase() === 'cncstatus';
});
let actSpindle = tags.find(t => (t.name || '').toLowerCase() === 'actspindle');
let actFeed = tags.find(t => (t.name || '').toLowerCase() === 'actfeed');

if (!statusObj && !cncStatusObj) return null;

let raw = statusObj ? (statusObj.value?.value ?? statusObj.value) : null;
let currentStatus;

if (statusObj && statusObj.status === 0 && (raw === '' || raw === null || raw === undefined)) {
    currentStatus = 'offline';
} else if (raw === '' || raw === null || raw === undefined) {
    currentStatus = null;
} else {
    let statusMap = { 1: 'running', 2: 'idle', 3: 'alarm', 4: 'offline' };
    currentStatus = statusMap[Number(raw)] || 'offline';
}

function num(v) {
    if (v === '' || v == null) return null;
    const n = Number(v);
    return isFinite(n) && Math.abs(n) < 1e12 ? n : null;
}
const sp = num(actSpindle?.value);
const fd = num(actFeed?.value);
const active = (sp != null && Math.abs(sp) > 1) || (fd != null && fd > 0 && fd < 1e6);
const cncText = String(cncStatusObj?.value || '').toUpperCase();
if (currentStatus === 'idle' && (active || /RUN|BUSY|CUT|CYCLE/.test(cncText))) {
    currentStatus = 'running';
}
if (!currentStatus) {
    if (/ALARM|ERROR|FAULT/.test(cncText)) currentStatus = 'alarm';
    else if (/RUN|BUSY|CUT|CYCLE/.test(cncText)) currentStatus = 'running';
    else if (/OFF/.test(cncText)) currentStatus = 'offline';
    else currentStatus = 'idle';
}

let prev = flow.get('CN01_previousStatus');
let lastSent = flow.get('CN01_lastSentTime') || 0;
let now = Date.now();

if (currentStatus === prev && (now - lastSent) < 30000) return null;

flow.set('CN01_previousStatus', currentStatus);
flow.set('CN01_lastSentTime', now);

const pmsBase = flow.get('pmsBase') || 'http://192.168.1.113:8010';
const machineId = flow.get('machineId') || 1;

msg.method = 'PATCH';
msg.url = pmsBase + '/api/machines/' + machineId + '/status';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { status: currentStatus, source: 'nodered' };
node.status({
    fill: currentStatus === 'running' ? 'green' : (currentStatus === 'alarm' ? 'red' : 'yellow'),
    shape: 'dot',
    text: 'StatusCode=' + raw + ' CncStatus=' + (cncStatusObj?.value || '?') + ' → ' + currentStatus
});
return msg;
